=====BOUNDED=====
/**
 * Length caps on the caller-controlled strings that land on an event: the
 * three intent-capture values the calling agent supplies, and the
 * `client_name`/`client_version` pair the client declares in its
 * `initialize` handshake. Without them a sink that batches writes in a
 * transaction (Cloudflare D1's `batch()`, for one) loses every unrelated
 * event in the flush when one oversized value fails its statement. Capping
 * in `instrument()` rather than in each sink means every sink, including
 * third-party and future ones, inherits the bound.
 *
 * `intent` is prose and takes the same 2000 as `error_message`.
 * `session_id`/`agent_id`/`client_name`/`client_version` are identifiers -
 * a UUID is 36 chars - so they take a much tighter cap. Oversized values are
 * truncated rather than dropped: losing the tail of an id is cheaper than
 * losing the event.
 */
export const MAX_INTENT_LENGTH = 2000;
export const MAX_IDENTIFIER_LENGTH = 128;

/** Returns `value` cut to `maxLength` UTF-16 code units, or null for a non-string. */
export function boundedString(value: unknown, maxLength: number): string | null {
  if (typeof value !== 'string') return null;
  if (value.length <= maxLength) return value;
  // slice() counts UTF-16 code units, so a naive cut at maxLength can land
  // between the two units of a surrogate pair (e.g. an emoji) and leave a
  // lone surrogate in the result - invalid UTF-16 that some UTF-8 encoders
  // (e.g. node-postgres) reject outright, which would make the value fail
  // the very sink write this bound exists to protect. Back the cut off by
  // one unit when it would split a pair.
  let end = maxLength;
  const code = value.charCodeAt(end - 1);
  if (code >= 0xd800 && code <= 0xdbff) end -= 1;
  return value.slice(0, end);
}

import type { McpServer } from '@modelcontextprotocol/server';
import type { Sink } from './sinks/types.js';
import type { ToolCallEvent } from './events.js';
import { classifyError } from './error-kind.js';
import { applyRedaction, type RedactionConfig } from './redaction.js';
import {
  extractAndStripIntent,
  injectIntentSchema,
  isIntentCaptureEnabled,
  schemaSupportsInjection,
  type IntentCaptureOption
} from './intent-capture.js';
import { EventBuffer } from './buffer.js';
import { boundedString, MAX_IDENTIFIER_LENGTH } from './bounded.js';

export interface InstrumentOptions {
  /** Required: this server's logical name. Not derivable from the McpServer instance (its `serverInfo` is private), so it's an explicit option. */
  serverName: string;
  serverVersion?: string;
  sinks: Sink[];
  /** Opt-in: capture tool arguments at all. Default false — no arguments are ever recorded unless this is true. */
  captureArguments?: boolean;
  redaction?: RedactionConfig;
  /** Opt-in: inject session_id/agent_id/intent into advertised tool schemas. Default false (off for every tool). */
  intentCapture?: IntentCaptureOption;
  /** Host-supplied user/org identity. The library never infers these itself. */
  resolveIdentity?: (ctx: {
    sessionId?: string;
  }) =>
    | { userId?: string; orgId?: string }
    | undefined
    | Promise<{ userId?: string; orgId?: string } | undefined>;
  bufferSize?: number;
  /** Pass `null` for manual mode: no interval timer, no `beforeExit` listener — flush explicitly via the returned handle's `flush()`. */
  flushIntervalMs?: number | null;
}

/**
 * Returned by `instrument()`. `server` is the same instance passed in
 * (instrumentation mutates it in place); use the handle's `server` rather
 * than your own pre-instrument reference so a future non-mutating
 * implementation doesn't silently drop instrumentation under you.
 */
export interface InstrumentHandle {
  server: McpServer;
  /** Flushes any buffered events immediately. On a request-scoped runtime (e.g. Cloudflare Workers), call this via `ctx.waitUntil(handle.flush())` before returning the response. */
  flush(): Promise<void>;
  /**
   * Shuts instrumentation down: a final `flush()`, then the interval timer
   * is cleared and the `beforeExit` listener removed. Call it when the host
   * disposes the server before the process ends - tests, hot reload, one
   * server per connection - so each `instrument()` call releases what it
   * registered. Idempotent. In manual mode (`flushIntervalMs: null`) there
   * is no timer or listener, so it is equivalent to `flush()`.
   */
  close(): Promise<void>;
}

interface ToolCallContext {
  sessionId?: string;
  http?: unknown;
}

interface ToolResultLike {
  content?: Array<{ type: string; text?: string }>;
  isError?: boolean;
}

// TextEncoder rather than Buffer.byteLength: this runs on every tool call,
// and Buffer only exists on Cloudflare Workers behind the nodejs_compat flag.
const encoder = new TextEncoder();

function byteLength(value: unknown): number {
  return encoder.encode(JSON.stringify(value) ?? '').length;
}

function extractErrorMessage(result: ToolResultLike): string | null {
  const text = (result.content ?? [])
    .filter(
      (block): block is { type: 'text'; text: string } =>
        block.type === 'text' && typeof block.text === 'string'
    )
    .map(block => block.text)
    .join(' ');
  if (!text) return null;
  return text.length > 2000 ? text.slice(0, 2000) : text;
}

/**
 * Wraps an `McpServer` so every tool registered through it (after this call)
 * records a `tool_call` event. This is the library's one required call —
 * call it immediately after constructing the server and before registering
 * any tools, since it works by wrapping `registerTool` itself.
 *
 * Nothing the library does around a tool call can change what the client
 * receives. The real handler always runs, its return value is passed through
 * unchanged, and a thrown error is re-thrown unchanged; this wrapper only
 * observes it. Every library-side step (request/response byte counting,
 * `resolveIdentity`, redaction, event construction, the buffer push) is
 * guarded: a failure is logged once per `instrument()` call via
 * `console.error`, then suppressed, and the step falls back to a neutral
 * value (`request_bytes`/`response_bytes` 0, empty identity, `arguments:
 * null`). A failing redactor therefore records `arguments: null`, never the
 * raw arguments. A failure inside a sink is handled separately by
 * EventBuffer, also logged once per sink.
 */
export function instrument(server: McpServer, options: InstrumentOptions): InstrumentHandle {
  const buffer = new EventBuffer({
    sinks: options.sinks,
    bufferSize: options.bufferSize,
    flushIntervalMs: options.flushIntervalMs
  });

  // Same "log once, then suppress" pattern EventBuffer uses per sink, scoped
  // to this instrument() call: one line is enough to surface a broken
  // resolver or redactor, and a line per tool call would drown the host's logs.
  let telemetryWarned = false;
  const warnOnce = (step: string, error: unknown): void => {
    if (telemetryWarned) return;
    telemetryWarned = true;
    console.error(
      `[mcpsignals] ${step} failed; the tool result is unaffected and further telemetry errors from this instrument() call are suppressed:`,
      error
    );
  };
  /** Runs one library-side step; on a throw, logs once and returns `fallback`. */
  const guarded = <T>(step: string, fn: () => T, fallback: T): T => {
    try {
      return fn();
    } catch (error) {
      warnOnce(step, error);
      return fallback;
    }
  };
  /** `guarded` for an async step: a throw or a rejection logs once and yields `fallback`. */
  const guardedAsync = async <T>(step: string, fn: () => Promise<T>, fallback: T): Promise<T> => {
    try {
      return await fn();
    } catch (error) {
      warnOnce(step, error);
      return fallback;
    }
  };

  const originalRegisterTool = server.registerTool.bind(server);

  server.registerTool = ((
    name: string,
    config: Record<string, unknown>,
    cb: (...args: unknown[]) => unknown
  ) => {
    const intentEnabled = isIntentCaptureEnabled(options.intentCapture, name);
    const originalInputSchema = config.inputSchema;
    const canInject = intentEnabled && schemaSupportsInjection(originalInputSchema);

    const wrappedConfig = canInject
      ? { ...config, inputSchema: injectIntentSchema(originalInputSchema) }
      : config;

    /**
     * Runs one tool call with telemetry around it. `invoke` receives the args
     * with any injected intent-capture keys stripped and must call the real
     * handler with the arity the SDK would have used for this registration.
     */
    const observeCall = async (
      args: Record<string, unknown>,
      ctx: ToolCallContext,
      invoke: (cleanArgs: Record<string, unknown>) => unknown
    ) => {
      const startedAt = new Date();
      const start = performance.now();

      // `JSON.stringify` throws on a BigInt (and on a throwing `toJSON`);
      // an unmeasurable request is recorded as 0 bytes, never blocks the handler.
      const requestBytes = guarded('request byte count', () => byteLength(args), 0);

      let cleanArgs = args;
      let sessionIdFromArgs: string | null = null;
      let agentId: string | null = null;
      let intent: string | null = null;
      if (canInject) {
        const extracted = extractAndStripIntent(args);
        cleanArgs = extracted.clean;
        sessionIdFromArgs = extracted.session_id;
        agentId = extracted.agent_id;
        intent = extracted.intent;
      }

      const sessionId = ctx.sessionId ?? sessionIdFromArgs ?? null;

      /**
       * Builds and pushes the event. Every caller wraps this in `guardedAsync`,
       * so a failure anywhere in here (identity, client info, redaction, the
       * buffer push) is logged once and the event is dropped, never surfaced
       * to the client. Redaction and `resolveIdentity` are guarded on their
       * own so a broken redactor or resolver still leaves an event behind,
       * recorded with `arguments: null` / a null identity.
       *
       * `durationMs` is measured by the caller the moment the handler settles.
       * `resolveIdentity` runs in here, after the handler, so its latency is
       * outside the timed window: `duration_ms` is wall time from call start
       * to response, per schema/events.md.
       */
      const push = async (
        durationMs: number,
        partial: Pick<ToolCallEvent, 'success' | 'error_kind' | 'error_message' | 'response_bytes'>
      ) => {
        // A host resolver that throws or rejects records a null identity.
        let identity: { userId?: string; orgId?: string } = {};
        try {
          identity = (await options.resolveIdentity?.({ sessionId: ctx.sessionId })) ?? {};
        } catch (error) {
          warnOnce('resolveIdentity', error);
        }
        // getClientVersion() is deprecated in favor of reading client identity off the
        // per-request `_meta` envelope, but the SDK's own deprecation note says the accessor
        // "remains functional" and is backfilled per request on 2026-07-28-era connections too.
        // Deliberately kept rather than reaching into the envelope's internal shape, which isn't
        // part of this SDK's stable public surface yet.
        //
        // The client declares its own name/version in the `initialize` handshake, so
        // both are caller-controlled and take the same identifier cap as the intent
        // fields (see bounded.ts). `tool_name` needs no cap: it is the registered name.
        const clientInfo = server.server.getClientVersion();
        const clientName = boundedString(clientInfo?.name, MAX_IDENTIFIER_LENGTH);
        const clientVersion = boundedString(clientInfo?.version, MAX_IDENTIFIER_LENGTH);
        const recordedArguments = guarded(
          'redaction',
          () => applyRedaction(cleanArgs, options.redaction, options.captureArguments),
          null
        );
        buffer.push({
          event_type: 'tool_call',
          ts: startedAt,
          server_name: options.serverName,
          server_version: options.serverVersion ?? null,
          tool_name: name,
          session_id: sessionId,
          agent_id: agentId,
          client_name: clientName,
          client_version: clientVersion,
          user_id: identity.userId ?? null,
          org_id: identity.orgId ?? null,
          duration_ms: durationMs,
          request_bytes: requestBytes,
          arguments: recordedArguments,
          intent,
          transport: ctx.http ? 'http' : 'stdio',
          ...partial
        });
      };

      // Only the handler call itself lives in this try: a throw here is the
      // handler's own, recorded and re-thrown unchanged. Recording happens
      // outside it so a telemetry failure can never be mistaken for one.
      let result: ToolResultLike;
      try {
        result = (await invoke(cleanArgs)) as ToolResultLike;
      } catch (error) {
        const durationMs = Math.round(performance.now() - start);
        await guardedAsync(
          'event recording',
          async () => {
            const message = error instanceof Error ? error.message : String(error);
            const truncated = message.length > 2000 ? message.slice(0, 2000) : message;
            await push(durationMs, {
              success: false,
              error_kind: classifyError(truncated),
              error_message: truncated,
              response_bytes: 0
            });
          },
          undefined
        );
        throw error;
      }

      const durationMs = Math.round(performance.now() - start);
      await guardedAsync(
        'event recording',
        async () => {
          const responseBytes = guarded('response byte count', () => byteLength(result), 0);
          if (result?.isError) {
            const errorMessage = extractErrorMessage(result);
            await push(durationMs, {
              success: false,
              error_kind: classifyError(errorMessage),
              error_message: errorMessage,
              response_bytes: responseBytes
            });
          } else {
            await push(durationMs, {
              success: true,
              error_kind: null,
              error_message: null,
              response_bytes: responseBytes
            });
          }
        },
        undefined
      );
      return result;
    };

    // The SDK's `createToolExecutor` picks the handler arity from the registered
    // `inputSchema` (same truthiness check as here): with a schema it calls
    // `(args, ctx)`; without one it calls `(ctx)` and never forwards the
    // arguments. The wrapper has to match that arity, otherwise the schema-less
    // handler gets the ctx object in `args` and `undefined` in `ctx`. Branch on
    // the final `wrappedConfig.inputSchema`, since intent capture may have
    // injected a schema into a registration that had none.
    //
    // On the schema-less path the SDK does not validate or pass the arguments,
    // so the wrapper records the call as an empty-arguments call (`args = {}`)
    // rather than reaching into the raw request for a payload the handler
    // never sees. `request_bytes` therefore matches a schema-backed tool
    // called with `{}`.
    const wrappedCb = wrappedConfig.inputSchema
      ? async (args: Record<string, unknown>, ctx: ToolCallContext) =>
          observeCall(args, ctx, cleanArgs => cb(cleanArgs, ctx))
      : async (ctx: ToolCallContext) => observeCall({}, ctx, () => cb(ctx));

    // The real `registerTool` overloads are exact per input/output schema shape; a
    // generic wrapper can't preserve that precision through a monkey-patch, so we
    // widen to `any` at this one call site rather than fighting the overload set.
    return (originalRegisterTool as (...args: unknown[]) => unknown)(
      name,
      wrappedConfig,
      wrappedCb
    );
  }) as typeof server.registerTool;

  return {
    server,
    flush: () => buffer.flush(),
    close: async () => {
      try {
        await buffer.flush();
      } finally {
        buffer.stop();
      }
    }
  };
}

=====BUFFER=====
import type { Sink } from './sinks/types.js';
import type { AnyEvent } from './events.js';

export interface EventBufferOptions {
  sinks: Sink[];
  bufferSize?: number;
  /**
   * Flush interval in ms. Pass `null` to disable the interval timer (and the
   * `beforeExit` listener) entirely — manual mode, for request-scoped
   * runtimes like Cloudflare Workers where a timer isn't guaranteed to fire
   * again before the isolate is evicted. In manual mode the caller is
   * responsible for calling `flush()` explicitly before the request ends
   * (e.g. `ctx.waitUntil(buffer.flush())`). Default: 5000.
   */
  flushIntervalMs?: number | null;
}

const DEFAULT_BUFFER_SIZE = 20;
const DEFAULT_FLUSH_INTERVAL_MS = 5000;

/**
 * Batches events and flushes on a size threshold or an interval, whichever
 * comes first, plus a best-effort flush on process shutdown. A sink whose
 * `write` throws or rejects is caught and logged at most once per sink
 * instance — it never propagates to the caller, and never blocks the other
 * sinks (all sinks are written in parallel via `allSettled`). Pass
 * `flushIntervalMs: null` for manual mode: no timer, no `beforeExit`
 * listener, the caller flushes explicitly.
 */
export class EventBuffer {
  private readonly sinks: Sink[];
  private readonly bufferSize: number;
  private queue: AnyEvent[] = [];
  private readonly warned = new WeakSet<Sink>();
  private readonly timer?: NodeJS.Timeout;
  // Chains every flush's write so `flush()` always waits for the ones ahead
  // of it, not just for its own batch. Without this, the size-triggered
  // `void this.flush()` in `push()` is fire-and-forget: a caller who awaits
  // a *later* `flush()` call (e.g. `ctx.waitUntil(handle.flush())` on
  // Workers, right before returning the response) can see an already-empty
  // queue and resolve immediately, while the earlier batch's sink write is
  // still in flight — on an isolate-based runtime that write can then be cut
  // off before it lands. Chaining onto `pending` makes every `flush()` call
  // resolve only once every write started before it has settled.
  private pending: Promise<void> = Promise.resolve();
  private readonly onBeforeExit = () => {
    void this.flush();
  };

  constructor(options: EventBufferOptions) {
    this.sinks = options.sinks;
    this.bufferSize = options.bufferSize ?? DEFAULT_BUFFER_SIZE;
    const manual = options.flushIntervalMs === null;

    if (!manual) {
      const flushIntervalMs = options.flushIntervalMs ?? DEFAULT_FLUSH_INTERVAL_MS;

      this.timer = setInterval(() => {
        void this.flush();
      }, flushIntervalMs);
      this.timer.unref?.();

      process.on('beforeExit', this.onBeforeExit);
    }
  }

  push(event: AnyEvent): void {
    this.queue.push(event);
    if (this.queue.length >= this.bufferSize) {
      void this.flush();
    }
  }

  flush(): Promise<void> {
    if (this.queue.length === 0) return this.pending;
    const batch = this.queue;
    this.queue = [];

    const write = this.writeBatch(batch);
    this.pending = this.pending.then(() => write);
    return this.pending;
  }

  private async writeBatch(batch: AnyEvent[]): Promise<void> {
    await Promise.allSettled(
      this.sinks.map(async sink => {
        try {
          await sink.write(batch);
        } catch (error) {
          if (!this.warned.has(sink)) {
            this.warned.add(sink);
            console.error(
              '[mcpsignals] sink failed, further errors from this sink are suppressed:',
              error
            );
          }
        }
      })
    );
  }

  /**
   * Clears the interval timer and removes the `beforeExit` listener. Safe to
   * call more than once and in manual mode: `clearInterval(undefined)` and
   * `process.off()` for a listener that is not registered are both no-ops.
   */
  stop(): void {
    clearInterval(this.timer);
    process.off('beforeExit', this.onBeforeExit);
  }
}
=====REDACTION=====
export interface RedactionConfig {
  /** Keys to record with their real value. If set, every key not listed here is type-only. */
  allow?: string[];
  /** Keys to always record as type-only, regardless of `allow`. */
  deny?: string[];
  /** Full override: receives the raw arguments, returns exactly what gets recorded. Wins over allow/deny. */
  redactor?: (args: Record<string, unknown>) => Record<string, unknown>;
}

function typeOnly(value: unknown): { __type: string } {
  return { __type: value === null ? 'null' : Array.isArray(value) ? 'array' : typeof value };
}

/**
 * Argument capture is opt-in (`captureArguments`). When on with no redaction
 * config, only key names and value *types* are recorded — never values. Real
 * values are recorded only for keys explicitly named in `allow`.
 */
export function applyRedaction(
  args: Record<string, unknown>,
  config: RedactionConfig | undefined,
  captureArguments: boolean | undefined
): Record<string, unknown> | null {
  if (!captureArguments) return null;

  if (config?.redactor) {
    return config.redactor(args);
  }

  const allow = config?.allow;
  const deny = config?.deny ?? [];

  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(args)) {
    const allowed = allow !== undefined && allow.includes(key) && !deny.includes(key);
    result[key] = allowed ? value : typeOnly(value);
  }
  return result;
}
=====ERRORKIND=====
import type { ErrorKind } from './events.js';

/**
 * Best-effort heuristic over free-text error messages. Not a structured
 * code — `success` is the ground truth for pass/fail. See schema/events.md
 * for the documented false-positive mode.
 */
export function classifyError(message: string | undefined | null): ErrorKind | null {
  if (!message) return null;

  if (/not found|does not exist|no such/i.test(message)) return 'not_found';
  if (/\bempty\b|no results?|nothing found|zero results/i.test(message)) return 'empty';
  if (/invalid|required|expected|must be|validation|schema/i.test(message)) return 'validation';
  return 'internal';
}

