import type { AnyEvent } from '../events.js';

export interface Sink {
  write(events: AnyEvent[]): Promise<void>;
}
=====CONSOLE=====
import type { Sink } from './types.js';
import type { AnyEvent } from '../events.js';

export interface ConsoleSinkOptions {
  /**
   * Where the JSON lines go. Defaults to `process.stdout`.
   *
   * On a stdio transport, stdout is the MCP wire: the spec says the server
   * MUST NOT write anything to stdout that is not a valid MCP message, and
   * MAY log to stderr. Pass `process.stderr` there.
   */
  stream?: NodeJS.WritableStream;
}

/** Zero-config default: writes one JSON line per event to stdout. */
export function consoleSink(options: ConsoleSinkOptions = {}): Sink {
  const stream = options.stream ?? process.stdout;
  return {
    async write(events: AnyEvent[]): Promise<void> {
      for (const event of events) {
        stream.write(JSON.stringify(event) + '\n');
      }
    }
  };
}
=====OTLP=====
import type { Sink } from './types.js';
import type { AnyEvent } from '../events.js';

/**
 * Emits one root span per `tool_call` event via the global OpenTelemetry
 * TracerProvider — this sink does not manage its own exporter, it relies on
 * whatever the host application already configured (the standard OTel
 * zero-code pattern). Requires the optional peer dependency
 * `@opentelemetry/api` only (not an SDK or exporter). Spans are never
 * parented to the context active at flush time; see the note at `startSpan`.
 *
 * Attribute mapping verified against the live `open-telemetry/semantic-
 * conventions-genai` repo (docs/gen-ai/mcp.md) as of this writing. Every
 * `gen_ai.*` / `mcp.*` attribute below is marked Development, not Stable —
 * expect these names to still move. Fields with no defined MCP/GenAI
 * convention are emitted as custom `mcpsignals.*` attributes rather than
 * forced into a semantically mismatched Stable attribute (see schema/
 * events.md's OTLP mapping note for the `transport` case specifically).
 * `session_summary` events have no span shape defined by the convention and
 * are not emitted by this sink.
 */
export function otlpSink(): Sink {
  return {
    async write(events: AnyEvent[]): Promise<void> {
      const otel = await import('@opentelemetry/api');
      const tracer = otel.trace.getTracer('mcpsignals');

      for (const event of events) {
        if (event.event_type !== 'tool_call') continue;

        // Events are written in batches, usually from inside whatever request
        // handler pushed the last event, so context.active() (the default
        // parent) belongs to an unrelated span. Start from ROOT_CONTEXT so
        // every tool call is its own root span.
        const span = tracer.startSpan(
          `tools/call ${event.tool_name}`,
          {
            kind: otel.SpanKind.SERVER,
            startTime: event.ts,
            attributes: {
              'gen_ai.operation.name': 'execute_tool',
              'gen_ai.tool.name': event.tool_name,
              ...(event.session_id !== null && { 'mcp.session.id': event.session_id }),
              ...(event.arguments !== null && {
                'gen_ai.tool.call.arguments': JSON.stringify(event.arguments)
              }),
              ...(event.intent !== null && { 'mcpsignals.intent': event.intent }),
              ...(event.agent_id !== null && { 'mcpsignals.agent.id': event.agent_id }),
              ...(event.user_id !== null && { 'enduser.id': event.user_id }),
              ...(event.org_id !== null && { 'mcpsignals.org.id': event.org_id }),
              'mcpsignals.server.name': event.server_name,
              ...(event.server_version !== null && {
                'mcpsignals.server.version': event.server_version
              }),
              ...(event.client_name !== null && { 'mcpsignals.client.name': event.client_name }),
              ...(event.client_version !== null && {
                'mcpsignals.client.version': event.client_version
              }),
              ...(event.transport !== null && { 'mcpsignals.transport': event.transport }),
              'mcpsignals.request.bytes': event.request_bytes,
              'mcpsignals.response.bytes': event.response_bytes,
              ...(event.error_kind !== null && { 'mcpsignals.error.kind': event.error_kind })
            }
          },
          otel.ROOT_CONTEXT
        );

        if (!event.success) {
          span.setAttribute('error.type', 'tool_error');
          span.setStatus({
            code: otel.SpanStatusCode.ERROR,
            message: event.error_message ?? undefined
          });
          if (event.error_message) {
            span.addEvent('exception', { 'exception.message': event.error_message });
          }
        } else {
          span.setStatus({ code: otel.SpanStatusCode.OK });
        }

        const endTime = new Date(event.ts.getTime() + event.duration_ms);
        span.end(endTime);
      }
    }
  };
}
=====D1=====
import type { Sink } from './types.js';
import type { AnyEvent } from '../events.js';

export interface D1SinkOptions {
  toolCallTable?: string;
  sessionSummaryTable?: string;
}

interface D1PreparedStatement {
  bind(...values: unknown[]): D1PreparedStatement;
}

interface D1Result {
  success: boolean;
  error?: string;
}

interface D1Database {
  prepare(query: string): D1PreparedStatement;
  batch(statements: D1PreparedStatement[]): Promise<D1Result[]>;
}

// developers.cloudflare.com/d1/platform/limits/: "Maximum string, BLOB or
// table row size: 2,000,000 bytes," and that limit applies per statement
// inside a batch(), same as everywhere else. `arguments` is the only
// caller-controlled field in schema/events.md without its own cap (upstream,
// error_message and intent are truncated to 2000 chars and the identifiers
// session_id/agent_id/client_name/client_version to 128, see bounded.ts), so
// it's the only column that can push a row anywhere near that ceiling.
// Capped well under it to leave headroom for the row's other columns.
const MAX_ARGUMENTS_BYTES = 1_000_000;

const encoder = new TextEncoder();

/**
 * Writes rows into the tables defined by schema/events.md's D1 DDL, via a
 * `D1Database` binding (Cloudflare Workers Worker Bindings API). Requires
 * `flushIntervalMs: null` (manual mode) on the buffer/instrument side, same
 * as any sink used from a request-scoped Workers runtime - see the Node
 * README's "Request-scoped runtimes" section.
 *
 * `db.batch()` is a SQL transaction: per the D1 docs, if one statement in
 * the batch fails, D1 aborts and rolls back the entire sequence, not just
 * that statement. An oversized `arguments` payload is therefore not left in
 * the batch to fail it - it's dropped (written as `null`) before binding,
 * with a warning logged at most once per sink instance.
 *
 * `ts` is written as an integer (Unix epoch milliseconds), not a string or
 * `Date`. SQLite's `datetime()` output (`"2026-09-01 23:25:24"`) does not
 * compare correctly against `Date#toISOString()` (`"2026-09-01T23:25:24.000Z"`)
 * - at index 10 `T` sorts above the space, so a `ts >= datetime('now', '-N
 * days')` filter silently includes the whole cutoff day. Read `ts` back out
 * with `unixepoch()` / `datetime(ts / 1000, 'unixepoch')`, not `datetime()`
 * on the raw column.
 *
 * The D1 docs don't spell out whether a failed statement inside `batch()`
 * rejects the promise or resolves with that entry's `success: false` -
 * `write()` checks the returned results either way, so a failure can't be
 * mistaken for a successful flush.
 */
export function d1Sink(db: D1Database, options: D1SinkOptions = {}): Sink {
  const toolCallTable = options.toolCallTable ?? 'mcpsignals_tool_call';
  const sessionSummaryTable = options.sessionSummaryTable ?? 'mcpsignals_session_summary';

  let warnedOversizedArguments = false;

  function boundArguments(args: Record<string, unknown> | null): string | null {
    if (args === null) return null;
    const json = JSON.stringify(args);
    if (encoder.encode(json).length > MAX_ARGUMENTS_BYTES) {
      if (!warnedOversizedArguments) {
        warnedOversizedArguments = true;
        console.error(
          `[mcpsignals] d1Sink: dropping an oversized \`arguments\` payload (over ${MAX_ARGUMENTS_BYTES} bytes) ` +
            'rather than risk D1 failing the whole batch; further occurrences this instance are suppressed.'
        );
      }
      return null;
    }
    return json;
  }

  return {
    async write(events: AnyEvent[]): Promise<void> {
      const statements: D1PreparedStatement[] = events.map(event => {
        if (event.event_type === 'tool_call') {
          return db
            .prepare(
              `insert into ${toolCallTable}
                (ts, server_name, server_version, tool_name, session_id, agent_id, client_name, client_version,
                 user_id, org_id, duration_ms, success, error_kind, error_message, request_bytes, response_bytes,
                 arguments, intent, transport)
               values (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`
            )
            .bind(
              event.ts.getTime(),
              event.server_name,
              event.server_version,
              event.tool_name,
              event.session_id,
              event.agent_id,
              event.client_name,
              event.client_version,
              event.user_id,
              event.org_id,
              event.duration_ms,
              event.success ? 1 : 0,
              event.error_kind,
              event.error_message,
              event.request_bytes,
              event.response_bytes,
              boundArguments(event.arguments),
              event.intent,
              event.transport
            );
        }

        return db
          .prepare(
            `insert into ${sessionSummaryTable}
              (ts, session_id, server_name, server_version, user_id, org_id, call_count, distinct_tools_used,
               wall_duration_ms, error_count)
             values (?,?,?,?,?,?,?,?,?,?)`
          )
          .bind(
            event.ts.getTime(),
            event.session_id,
            event.server_name,
            event.server_version,
            event.user_id,
            event.org_id,
            event.call_count,
            event.distinct_tools_used,
            event.wall_duration_ms,
            event.error_count
          );
      });

      if (statements.length === 0) return;
      const results = await db.batch(statements);
      const failed = results.filter(result => !result.success);
      if (failed.length > 0) {
        throw new Error(
          `[mcpsignals] d1Sink: db.batch() reported ${failed.length} of ${results.length} ` +
            `statement(s) failed: ${failed.map(result => result.error ?? 'unknown error').join('; ')}`
        );
      }
    }
  };
}

=====POSTGRES=====
import type { Sink } from './types.js';
import type { AnyEvent, SessionSummaryEvent, ToolCallEvent } from '../events.js';

export interface PostgresSinkOptions {
  /** An existing `pg` Pool to reuse. If omitted, a new Pool is created from `pg`'s own env var defaults (PGHOST, PGUSER, PGPASSWORD, PGDATABASE, PGPORT, or a `connectionString`). */
  pool?: unknown;
  connectionString?: string;
  toolCallTable?: string;
  sessionSummaryTable?: string;
}

interface QueryablePool {
  query: (text: string, values: unknown[]) => Promise<unknown>;
}

const TOOL_CALL_COLUMNS = [
  'ts',
  'server_name',
  'server_version',
  'tool_name',
  'session_id',
  'agent_id',
  'client_name',
  'client_version',
  'user_id',
  'org_id',
  'duration_ms',
  'success',
  'error_kind',
  'error_message',
  'request_bytes',
  'response_bytes',
  'arguments',
  'intent',
  'transport'
] as const;

const SESSION_SUMMARY_COLUMNS = [
  'ts',
  'session_id',
  'server_name',
  'server_version',
  'user_id',
  'org_id',
  'call_count',
  'distinct_tools_used',
  'wall_duration_ms',
  'error_count'
] as const;

function toolCallRow(event: ToolCallEvent): unknown[] {
  return TOOL_CALL_COLUMNS.map(column => event[column]);
}

function sessionSummaryRow(event: SessionSummaryEvent): unknown[] {
  return SESSION_SUMMARY_COLUMNS.map(column => event[column]);
}

/**
 * Builds one `insert into <table> (cols) values ($1,...),($n+1,...),...`
 * statement for all rows, with a flat bind array in column order. `pg`
 * encodes each bound value itself (Date -> timestamp string, plain object ->
 * JSON), so rows are passed through as-is.
 *
 * Postgres caps a statement at 65535 bind parameters; at 19 columns that is
 * 3449 rows per statement, far above the default buffer size of 20, so the
 * rows are not chunked.
 */
function buildMultiRowInsert(
  table: string,
  columns: readonly string[],
  rows: unknown[][]
): { text: string; values: unknown[] } {
  const values: unknown[] = [];
  const tuples: string[] = [];
  for (const row of rows) {
    const placeholders = row.map((_, i) => `$${values.length + i + 1}`);
    tuples.push(`(${placeholders.join(',')})`);
    values.push(...row);
  }
  const text = `insert into ${table} (${columns.join(', ')}) values ${tuples.join(',')}`;
  return { text, values };
}

/**
 * Writes rows into the tables defined by schema/events.md's Postgres DDL.
 * Requires the optional peer dependency `pg` — dynamically imported so it
 * isn't required unless this sink is actually used.
 *
 * Each `write()` issues at most one multi-row insert per table: one for
 * the tool_call rows and one for the session_summary rows in the batch.
 */
export function postgresSink(options: PostgresSinkOptions = {}): Sink {
  const toolCallTable = options.toolCallTable ?? 'mcpsignals_tool_call';
  const sessionSummaryTable = options.sessionSummaryTable ?? 'mcpsignals_session_summary';

  let poolPromise: Promise<QueryablePool> | undefined;

  async function getPool() {
    if (!poolPromise) {
      poolPromise = (async () => {
        if (options.pool) {
          return options.pool as QueryablePool;
        }
        const pg = await import('pg');
        const Pool = pg.Pool ?? pg.default.Pool;
        return new Pool(
          options.connectionString ? { connectionString: options.connectionString } : undefined
        );
      })();
    }
    return poolPromise;
  }

  return {
    async write(events: AnyEvent[]): Promise<void> {
      const toolCallRows: unknown[][] = [];
      const sessionSummaryRows: unknown[][] = [];
      for (const event of events) {
        if (event.event_type === 'tool_call') {
          toolCallRows.push(toolCallRow(event));
        } else {
          sessionSummaryRows.push(sessionSummaryRow(event));
        }
      }
      if (toolCallRows.length === 0 && sessionSummaryRows.length === 0) {
        return;
      }

      const pool = await getPool();
      if (toolCallRows.length > 0) {
        const { text, values } = buildMultiRowInsert(
          toolCallTable,
          TOOL_CALL_COLUMNS,
          toolCallRows
        );
        await pool.query(text, values);
      }
      if (sessionSummaryRows.length > 0) {
        const { text, values } = buildMultiRowInsert(
          sessionSummaryTable,
          SESSION_SUMMARY_COLUMNS,
          sessionSummaryRows
        );
        await pool.query(text, values);
      }
    }
  };
}
=====BIGQUERY=====
import type { Sink } from './types.js';
import type { AnyEvent } from '../events.js';

export interface BigQuerySinkOptions {
  /** An existing `@google-cloud/bigquery` client to reuse. If omitted, one is created from Application Default Credentials. */
  client?: unknown;
  /** BigQuery project id. Defaults to the client library's own ADC-based resolution. */
  projectId?: string;
  dataset?: string;
  toolCallTable?: string;
  sessionSummaryTable?: string;
}

interface BigQueryTable {
  insert(rows: Record<string, unknown>[]): Promise<unknown>;
}
interface BigQueryClient {
  dataset(name: string): { table(name: string): BigQueryTable };
}

/**
 * Streams rows into the tables defined by schema/events.md's BigQuery DDL.
 * Requires the optional peer dependency `@google-cloud/bigquery` —
 * dynamically imported so it isn't required unless this sink is actually
 * used. Credentials come from Application Default Credentials, same as the
 * client library's own defaults.
 */
export function bigquerySink(options: BigQuerySinkOptions = {}): Sink {
  const dataset = options.dataset ?? 'mcpsignals';
  const toolCallTable = options.toolCallTable ?? 'tool_call';
  const sessionSummaryTable = options.sessionSummaryTable ?? 'session_summary';

  let clientPromise: Promise<BigQueryClient> | undefined;

  async function getClient(): Promise<BigQueryClient> {
    if (!clientPromise) {
      clientPromise = (async () => {
        if (options.client) {
          return options.client as BigQueryClient;
        }
        const mod = await import('@google-cloud/bigquery');
        const BigQuery = mod.BigQuery;
        return new BigQuery(
          options.projectId ? { projectId: options.projectId } : undefined
        ) as unknown as BigQueryClient;
      })();
    }
    return clientPromise;
  }

  return {
    async write(events: AnyEvent[]): Promise<void> {
      const client = await getClient();
      const toolCalls = events.filter(
        (e): e is Extract<AnyEvent, { event_type: 'tool_call' }> => e.event_type === 'tool_call'
      );
      const sessionSummaries = events.filter(
        (e): e is Extract<AnyEvent, { event_type: 'session_summary' }> =>
          e.event_type === 'session_summary'
      );

      if (toolCalls.length > 0) {
        await client
          .dataset(dataset)
          .table(toolCallTable)
          .insert(
            toolCalls.map(e => ({
              ts: e.ts.toISOString(),
              server_name: e.server_name,
              server_version: e.server_version,
              tool_name: e.tool_name,
              session_id: e.session_id,
              agent_id: e.agent_id,
              client_name: e.client_name,
              client_version: e.client_version,
              user_id: e.user_id,
              org_id: e.org_id,
              duration_ms: e.duration_ms,
              success: e.success,
              error_kind: e.error_kind,
              error_message: e.error_message,
              request_bytes: e.request_bytes,
              response_bytes: e.response_bytes,
              arguments: e.arguments ? JSON.stringify(e.arguments) : null,
              intent: e.intent,
              transport: e.transport
            }))
          );
      }

      if (sessionSummaries.length > 0) {
        await client
          .dataset(dataset)
          .table(sessionSummaryTable)
          .insert(
            sessionSummaries.map(e => ({
              ts: e.ts.toISOString(),
              session_id: e.session_id,
              server_name: e.server_name,
              server_version: e.server_version,
              user_id: e.user_id,
              org_id: e.org_id,
              call_count: e.call_count,
              distinct_tools_used: e.distinct_tools_used,
              wall_duration_ms: e.wall_duration_ms,
              error_count: e.error_count
            }))
          );
      }
    }
  };
}

# mcpsignals (Node.js)

Drop-in instrumentation for MCP servers. Wrap your server, point it at a
sink, and it records what agents did with your tools into a database you
own - no hosted service, no account, no per-session pricing.

Requires **Node.js 20 or newer**. See the [root README](../../README.md) for
the redaction model, the sink comparison, and intent capture, and
[`schema/events.md`](../../schema/events.md) for the event field reference.

## Install

```bash
npm install mcpsignals @modelcontextprotocol/server zod
```

`@modelcontextprotocol/server` (v2) and `zod` are peer dependencies - you
already have them if you have an MCP server. Warehouse clients (`pg`,
`@google-cloud/bigquery`, `@opentelemetry/api`) are optional peer
dependencies: only install the one for the sink you use.

## Usage

`instrument()` wraps `registerTool` itself, so it must be called **right
after constructing your server and before registering any tools**.

```ts
import { McpServer } from '@modelcontextprotocol/server';
import { instrument, consoleSink } from 'mcpsignals';

const server = new McpServer({ name: 'my-server', version: '1.0.0' });

instrument(server, {
  serverName: 'my-server',
  serverVersion: '1.0.0',
  sinks: [consoleSink()]
});

server.registerTool(/* ...as normal, nothing else changes... */);
```

On a stdio transport pass `consoleSink({ stream: process.stderr })`, because
the MCP spec reserves stdout for protocol messages and `StdioServerTransport`
writes to the same `process.stdout` the default sink uses.

Argument capture is off by default. Turn it on and record only key names
and value types with:

```ts
instrument(server, {
  serverName: 'my-server',
  sinks: [consoleSink()],
  captureArguments: true
});
```

See the root README's redaction section before enabling `redaction.allow`
to record real argument values.

## Shutting instrumentation down

`instrument()` returns a handle:
`{ server, flush(): Promise<void>, close(): Promise<void> }`. In default
mode every `instrument()` call starts an interval timer and adds one
`beforeExit` listener. If your host disposes the server before the process
ends (tests, hot reload, one server per connection), call `close()` when
you dispose it. `close()` runs a final `flush()`, then clears the timer and
removes the listener. It is safe to call more than once. Manual mode
(`flushIntervalMs: null`, below) has no timer or listener to release, so
there `close()` behaves like `flush()`.

```ts
const handle = instrument(server, { serverName: 'my-server', sinks: [consoleSink()] });
// ...later, when the server is disposed:
await handle.close();
```

## Request-scoped runtimes (Cloudflare Workers)

On a long-lived Node process, ignore the handle - the interval timer and the
`beforeExit` listener flush for you. On a request-scoped, isolate-based
runtime, neither of those is reliable: the isolate can be evicted the
instant the response is sent, with no guarantee a `setInterval` fires again
before that happens, and `process`'s `beforeExit` doesn't correspond to "this
invocation is ending" outside Node.

Pass `flushIntervalMs: null` to disable the timer and the `beforeExit`
listener entirely, construct the server fresh per request (the correct
pattern here regardless, so a module-scope server doesn't close over one
request's auth context), and flush explicitly via `ctx.waitUntil()` before
returning:

```ts
import { McpServer } from '@modelcontextprotocol/server';
import { instrument, d1Sink } from 'mcpsignals';

interface Env {
  DB: D1Database;
}

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext) {
    const server = new McpServer({ name: 'my-server', version: '1.0.0' });
    const { flush } = instrument(server, {
      serverName: 'my-server',
      sinks: [d1Sink(env.DB)],
      flushIntervalMs: null // manual mode: no timer, no beforeExit listener
    });

    server.registerTool(/* ...as normal... */);

    // ...connect server to your transport, handle the request, and get a response...
    const response = await handleRequest(request, server);

    ctx.waitUntil(flush());
    return response;
  }
};
```

In manual mode, `instrument()` and `d1Sink` use no Node-only globals, so
they run on Workers without the `nodejs_compat` compatibility flag.
`consoleSink()` writes to `process.stdout`, which Workers doesn't provide,
so use `d1Sink` (or another sink) there.

### Known limitation: `client_name`/`client_version` will be null

This pattern - a fresh `McpServer` per request - has a consequence worth
knowing about up front: `client_name`/`client_version` on every `tool_call`
event will be `null`, for every caller, on every request.

The library reads client identity via `server.server.getClientVersion()`
(the low-level `Server` instance underneath `McpServer`, exposed via its
`.server` property), which only returns a value once that specific
`McpServer` instance has processed an `initialize` request and the SDK has
stored the client's `clientInfo` on it. But `initialize` and a later
`tools/call` are two separate HTTP
requests, each getting its own fresh `McpServer` per the pattern above - so
the instance handling `tools/call` never itself saw `initialize`, and
`getClientVersion()` has nothing to return. This isn't a Node-only or
Workers-only quirk of the SDK you can configure around; it falls directly
out of "construct the server fresh per request," which this section
recommends as the correct pattern regardless of the runtime.

If you need `client_name`/`client_version` populated in this shape, read
`clientInfo` off the raw JSON-RPC `initialize` request yourself, before it
ever reaches the SDK or `instrument()`, and persist it somewhere your
`tools/call` handler can read it back by whatever identity you already
have for the caller (an account id, an API key, a DID - whatever your auth
layer resolves). Then pass it through as a fallback wherever you build your
own event/row from the library's output, for every event where the
library-observed `client_name`/`client_version` is null. `instrument()`
itself has no option for this - there is no per-connection state on a
request-scoped runtime for it to hang the value off, so the SDK's own
capture mechanism is fundamentally unavailable here, not just failing to be
configured. Storage and fallback are entirely your application's concern,
independent of this library.

## Sinks

```ts
import { postgresSink, bigquerySink, otlpSink, d1Sink } from 'mcpsignals';
```

Each sink pulls credentials from its own client library's usual defaults
(env vars, Application Default Credentials, or the global OTel
TracerProvider) - there's no mcpsignals-specific config file.

### D1

`d1Sink(db, options?)` takes a `D1Database` binding directly - there's no
client library to load credentials from, since the binding is already
authenticated. Create the tables from `schema/events.md`'s D1 DDL first
(via `wrangler d1 migrations`, not by hand - see that file for why).

```ts
import { McpServer } from '@modelcontextprotocol/server';
import { instrument, d1Sink } from 'mcpsignals';

interface Env {
  DB: D1Database;
}

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext) {
    const server = new McpServer({ name: 'my-server', version: '1.0.0' });
    const { flush } = instrument(server, {
      serverName: 'my-server',
      sinks: [d1Sink(env.DB)],
      flushIntervalMs: null // manual mode - see "Request-scoped runtimes" above
    });

    server.registerTool(/* ...as normal... */);

    const response = await handleRequest(request, server);

    ctx.waitUntil(flush());
    return response;
  }
};
```

`d1Sink` handles the constraints that are easy to miss when hand-rolling a
D1 sink: `db.batch()` is a transaction (one bad row rolls back the whole
flush), so an oversized `arguments` payload is dropped rather than left in
the batch to fail it; and `ts` is written as Unix epoch milliseconds rather
than an ISO string, because SQLite's `datetime()` output doesn't compare
correctly against `toISOString()`'s. See the `d1Sink` doc comment
(`src/sinks/d1.ts`) and `schema/events.md`'s D1 section for the full
reasoning.

